```

```c
// json.c (minimal implementation)
#include <stdlib.h>
#include <string.h>
#include "json.h"

const char* get_json_record(const char* key, int* err){
  if(!key){ if(err) *err = 1; return NULL; }
  const char* json = "{\"key\":\"value\"}";
  char* buf = (char*)malloc(strlen(json) + 1);
  if(!buf){ if(err) *err = 2; return NULL; }
  strcpy(buf, json);
  if(err) *err = 0;
  return buf; // caller must free
}
```

```go
// json_bind.go
package main

/*
#include "json.h"
*/
import "C"
import (
  "fmt"
  "sync"
  "unsafe"
)

func GetJSONRecord(key string) (string, error) {
  ck := C.CString(key)
  defer C.free(unsafe.Pointer(ck))
  var err C.int
  cstr := C.get_json_record(ck, &err)
  if cstr == nil {
    return "", fmt.Errorf("C error %d", int(err))
  }
  s := C.GoString(cstr)
  C.free(unsafe.Pointer(cstr))
  return s, nil
}

func main() {
  var wg sync.WaitGroup
  wg.Add(2)
  go func(){ defer wg.Done(); if s, e := GetJSONRecord("alpha"); e == nil { println(s) } }()
  go func(){ defer wg.Done(); if s, e := GetJSONRecord("beta"); e == nil { println(s) } }()
  wg.Wait()
}
```

